import { hmacSha256 } from './hmac.mjs';
import { b64urlEncode, b64urlDecode } from './base64url.mjs';
import { pyJsonDumps } from './pyjson.mjs';

function utf8Bytes(str) {
  return new Uint8Array(Buffer.from(str, 'utf8'));
}

export function jwtEncode(payload, secret) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const headerJson = pyJsonDumps(header);
  const payloadJson = pyJsonDumps(payload);
  const signingInput = b64urlEncode(utf8Bytes(headerJson)) + '.' + b64urlEncode(utf8Bytes(payloadJson));
  const signature = hmacSha256(utf8Bytes(secret), utf8Bytes(signingInput));
  return signingInput + '.' + b64urlEncode(signature);
}

export function jwtDecode(token, secret, options, algorithms) {
  const parts = String(token).split('.');
  if (parts.length !== 3) {
    throw new Error('Not enough segments');
  }
  const [headerB64, payloadB64, signatureB64] = parts;

  const header = JSON.parse(Buffer.from(b64urlDecode(headerB64)).toString('utf8'));
  if (algorithms && !algorithms.includes(header.alg)) {
    throw new Error('The specified alg value is not allowed');
  }

  const signingInput = headerB64 + '.' + payloadB64;
  const expectedSignature = hmacSha256(utf8Bytes(secret), utf8Bytes(signingInput));
  if (b64urlEncode(expectedSignature) !== signatureB64) {
    throw new Error('Signature verification failed.');
  }

  const claims = JSON.parse(Buffer.from(b64urlDecode(payloadB64)).toString('utf8'));

  if (options && options.verify_iat && 'iat' in claims) {
    if (typeof claims.iat !== 'number' || !Number.isInteger(claims.iat)) {
      throw new Error('Issued At claim (iat) must be an integer.');
    }
  }

  return claims;
}

