    console.error(`${prog}: error: ${msg}`);
    process.exit(2);
  };
  const help = () => {
    console.log(usage + '\n\noptions:\n  -h, --help            show this help message and exit\n  --data DATA\n  --verify_iat {true,false}');
    process.exit(0);
  };
  const result = { data: undefined, verify_iat: undefined };
  const unknown = [];
  for (let i = 0; i < argv.length; i++) {
    let a = argv[i];
    let inline;
    if (a.startsWith('--') && a.includes('=')) {
      inline = a.slice(a.indexOf('=') + 1);
      a = a.slice(0, a.indexOf('='));
    }
    if (a === '-h' || a === '--help') help();
    else if (a === '--data' || a === '--verify_iat') {
      let v = inline;
