// Pure-JS HMAC-SHA256 (RFC 2104), 64-byte block size.

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(keyBytes /* Uint8Array */, msgBytes /* Uint8Array */) /* Uint8Array */ {
  let key = keyBytes;
  if (key.length > BLOCK_SIZE) {
    key = sha256(key);
  }
  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(key);

  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);
