// Pure-JS HMAC-SHA256 (RFC 2104), 64-byte block size.

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(keyBytes /* Uint8Array */, msgBytes /* Uint8Array */) /* Uint8Array */ {
  let key = keyBytes;
  if (key.length > BLOCK_SIZE) {
    key = sha256(key);
  }
  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(key);

  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    innerPad[i] = paddedKey[i] ^ 0x36;
    outerPad[i] = paddedKey[i] ^ 0x5c;
  }

  const inner = new Uint8Array(BLOCK_SIZE + msgBytes.length);
  inner.set(innerPad);
  inner.set(msgBytes, BLOCK_SIZE);
  const innerHash = sha256(inner);

  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(outerPad);
  outer.set(innerHash, BLOCK_SIZE);
  return sha256(outer);
}

