import { sha256 } from '/output/lib/sha256.mjs';
import { hmacSha256 } from '/output/lib/hmac.mjs';
import { createHash, createHmac, randomBytes } from 'node:crypto';

const hex = (u8) => Array.from(u8, b => b.toString(16).padStart(2, '0')).join('');
const te = new TextEncoder();
let fail = 0;
const check = (name, got, want) => {
  const ok = got === want;
  if (!ok) fail++;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${ok ? '' : ` got=${got} want=${want}`}`);
};

// Known vectors
check('sha256("")', hex(sha256(te.encode(''))), 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');
check('sha256("abc")', hex(sha256(te.encode('abc'))), 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
check('hmac("key", fox)', hex(hmacSha256(te.encode('key'), te.encode('The quick brown fox jumps over the lazy dog'))), 'f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8');

// Boundary lengths (0,1,54,55,56,63,64,65,100,1000,1000000) vs node:crypto
for (const len of [0, 1, 54, 55, 56, 63, 64, 65, 100, 128, 1000, 1000000]) {
  const buf = randomBytes(len);
  const got = hex(sha256(new Uint8Array(buf)));
  const want = createHash('sha256').update(buf).digest('hex');
  check(`sha256(random len=${len})`, got, want);
}

// HMAC: empty msg, key lengths 0, 63, 64, 65, 200
for (const klen of [0, 63, 64, 65, 200]) {
  const key = randomBytes(klen);
  const msg = randomBytes(37);
  const got = hex(hmacSha256(new Uint8Array(key), new Uint8Array(msg)));
  const want = createHmac('sha256', key).update(msg).digest('hex');
  check(`hmac(keylen=${klen})`, got, want);
}
check('hmac(key,empty msg)', hex(hmacSha256(te.encode('key'), new Uint8Array(0))),
  createHmac('sha256', 'key').update('').digest('hex'));

process.exit(fail ? 1 : 0);

