import { jwtEncode, jwtDecode } from '/tmp/lib/jwt.mjs';

// Round-trip with the contract's reference values
const token = jwtEncode({ info: 'hello', iat: 1786345209 }, 'secret');
console.log('token:', token);
console.log('prefix ok:', token.startsWith('eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.'));

const decoded = jwtDecode(token, 'secret', { verify_iat: true }, ['HS256']);
console.log('decoded:', JSON.stringify(decoded));
console.log('equal:', decoded.info === 'hello' && decoded.iat === 1786345209);

// Non-ASCII payload (ensure_ascii escaping)
const t2 = jwtEncode({ info: 'héllo中文' }, 'secret');
console.log('non-ascii token payload segment:', t2.split('.')[1]);
console.log('roundtrip non-ascii:', JSON.stringify(jwtDecode(t2, 'secret', { verify_iat: false }, ['HS256'])));

// Error cases
const expect = (fn, msg) => {
  try { fn(); console.log('FAIL: no throw for', msg); }
  catch (e) { console.log(e.message === msg ? 'ok:' : 'FAIL (' + e.message + ') expected:', msg); }
};
expect(() => jwtDecode(token, 'wrongsecret', { verify_iat: true }, ['HS256']), 'Signature verification failed.');
expect(() => jwtDecode(token, 'secret', { verify_iat: true }, ['HS512']), 'The specified alg value is not allowed');
