// argparse.mjs - minimal manual mimic of Python's argparse for the test17 CLI.
// Supports: --data (required, takes a value), --verify_iat (required,
// choices 'true'/'false'), -h/--help. Accepts "--opt value" and "--opt=value"
// forms in any order. Errors print usage + message to stderr and exit(2);
// help prints to stdout and exits 0. No imports.

function usageLine(prog) {
  return `usage: ${prog} [-h] --data DATA --verify_iat {true,false}`;
}

function helpText(prog) {
  return `${usageLine(prog)}

options:
  -h, --help            show this help message and exit
  --data DATA
  --verify_iat {true,false}`;
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + "\n");
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// argparse treats a token starting with '-' as option-like (and therefore not
// consumable as a value), except negative numbers when no option looks like
// a negative number.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  return token.length > 1 && token[0] === "-" && !NEGATIVE_NUMBER.test(token);
}

export function parseArgs(argv, prog) {
  const result = { data: undefined, verify_iat: undefined };
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];

    if (arg === "-h" || arg === "--help") {
      process.stdout.write(helpText(prog) + "\n");
      process.exit(0);
    }

    let name = null;
    let inlineValue = null;
    if (arg === "--data" || arg === "--verify_iat") {
      name = arg;
    } else if (arg.startsWith("--data=")) {
      name = "--data";
      inlineValue = arg.slice("--data=".length);
    } else if (arg.startsWith("--verify_iat=")) {
      name = "--verify_iat";
      inlineValue = arg.slice("--verify_iat=".length);
    } else {
      unrecognized.push(arg);
      i += 1;
      continue;
    }

    let value;
    if (inlineValue !== null) {
      value = inlineValue;
      i += 1;
    } else {
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        fail(prog, `argument ${name}: expected one argument`);
      }
      value = next;
      i += 2;
    }

    if (name === "--verify_iat" && value !== "true" && value !== "false") {
      fail(
        prog,
        `argument --verify_iat: invalid choice: '${value}' (choose from 'true', 'false')`
      );
    }

    result[name.slice(2)] = value;
  }

  const missing = [];
  if (result.data === undefined) missing.push("--data");
  if (result.verify_iat === undefined) missing.push("--verify_iat");
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(", ")}`);
  }
  if (unrecognized.length > 0) {
    fail(prog, `unrecognized arguments: ${unrecognized.join(" ")}`);
  }

  return result;
}

