// RFC 4648 §5 base64url encoding/decoding, no padding.
// Pure JS — no external dependencies.

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

const REVERSE = (() => {
  const table = new Int8Array(128).fill(-1);
  for (let i = 0; i < ALPHABET.length; i++) {
    table[ALPHABET.charCodeAt(i)] = i;
  }
  return table;
})();

export function b64urlEncode(bytes) {
  let out = '';
  let i = 0;
  for (; i + 3 <= bytes.length; i += 3) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    out += ALPHABET[(n >> 18) & 63] +
           ALPHABET[(n >> 12) & 63] +
           ALPHABET[(n >> 6) & 63] +
           ALPHABET[n & 63];
  }
  const rem = bytes.length - i;
  if (rem === 1) {
    const n = bytes[i] << 16;
    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63];
  } else if (rem === 2) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8);
    out += ALPHABET[(n >> 18) & 63] +
           ALPHABET[(n >> 12) & 63] +
           ALPHABET[(n >> 6) & 63];
  }
  return out;
}

export function b64urlDecode(str) {
  const s = String(str).replace(/=+$/, ''); // tolerate padding, accept unpadded
  const out = [];
  let acc = 0;
  let nbits = 0;
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    const v = code < 128 ? REVERSE[code] : -1;
    if (v < 0) {
      throw new Error('Invalid base64url character: ' + s[i]);
    }
    acc = (acc << 6) | v;
    nbits += 6;
    if (nbits >= 8) {
      nbits -= 8;
      out.push((acc >> nbits) & 0xff);
    }
  }
  return new Uint8Array(out);
}

