// Python repr() semantics for the subset: strings, numbers, booleans,
// null (None), arrays (lists), plain objects (dicts).

// A character is non-printable (per Python str.isprintable) when it is in a
// Unicode "Other" (C*) or "Separator" (Z*) category — except U+0020 SPACE.
const NON_PRINTABLE = /[\p{C}\p{Z}]/u;

function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function reprString(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  // Python prefers single quotes; switch to double quotes only when the
  // string contains a single quote but no double quote.
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) { // iterates by code point
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (isPrintable(ch)) {
      out += ch; // printable non-ASCII (é, 中, emoji) printed literally
    } else if (cp <= 0xff) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else if (cp <= 0xffff) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      out += '\\U' + cp.toString(16).padStart(8, '0');
    }
  }
  return out + quote;
}

function reprNumber(n) {
  if (Number.isInteger(n)) {
    return String(n);
  }
  return String(n);
}

export function pyRepr(value) {
  if (value === null || value === undefined) {
    return 'None';
  }
  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }
  if (typeof value === 'number') {
    return reprNumber(value);
  }
  if (typeof value === 'string') {
    return reprString(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (typeof value === 'object') {
    const entries = Object.keys(value).map(
      (k) => reprString(k) + ': ' + pyRepr(value[k])
    );
    return '{' + entries.join(', ') + '}';
  }
  throw new TypeError('pyRepr: unsupported type: ' + typeof value);
}

