import { spawnSync } from "node:child_process";

const USAGE = "usage: test17.mjs [-h] --data DATA --verify_iat {true,false}";
const HELP = `${USAGE}

options:
  -h, --help            show this help message and exit
  --data DATA
  --verify_iat {true,false}
`;

const cases = [
  {
    name: "valid space form",
    args: ["--data", "hello", "--verify_iat", "true"],
    code: 0,
    stdout: '{"data":"hello","verify_iat":"true"}\n',
    stderr: "",
  },
  {
    name: "valid inline form, reversed order",
    args: ["--verify_iat=false", "--data=hello world"],
    code: 0,
    stdout: '{"data":"hello world","verify_iat":"false"}\n',
    stderr: "",
  },
  {
    name: "empty inline value",
    args: ["--data=", "--verify_iat=true"],
    code: 0,
    stdout: '{"data":"","verify_iat":"true"}\n',
    stderr: "",
  },
  {
    name: "missing --verify_iat",
    args: ["--data", "x"],
    code: 2,
    stdout: "",
    stderr: `${USAGE}\ntest17.mjs: error: the following arguments are required: --verify_iat\n`,
  },
  {
    name: "missing both",
    args: [],
    code: 2,
    stdout: "",
    stderr: `${USAGE}\ntest17.mjs: error: the following arguments are required: --data, --verify_iat\n`,
  },
  {
    name: "missing --data",
    args: ["--verify_iat", "true"],
    code: 2,
    stdout: "",
    stderr: `${USAGE}\ntest17.mjs: error: the following arguments are required: --data\n`,
  },
  {
    name: "bad choice",
    args: ["--data", "x", "--verify_iat", "yes"],
    code: 2,
    stdout: "",
    stderr: `${USAGE}\ntest17.mjs: error: argument --verify_iat: invalid choice: 'yes' (choose from 'true', 'false')\n`,
  },
  {
    name: "unknown arg",
    args: ["--data", "x", "--verify_iat", "true", "--foo"],
    code: 2,
    stdout: "",
    stderr: `${USAGE}\ntest17.mjs: error: unrecognized arguments: --foo\n`,
  },
  {
    name: "unknown positional",
    args: ["--data", "x", "--verify_iat", "true", "extra"],
    code: 2,
    stdout: "",
    stderr: `${USAGE}\ntest17.mjs: error: unrecognized arguments: extra\n`,
  },
  {
    name: "missing value at end",
    args: ["--verify_iat", "true", "--data"],
    code: 2,
    stdout: "",
    stderr: `${USAGE}\ntest17.mjs: error: argument --data: expected one argument\n`,
  },
  {
    name: "value looks like option",
    args: ["--data", "--verify_iat", "true"],
    code: 2,
    stdout: "",
    stderr: `${USAGE}\ntest17.mjs: error: argument --data: expected one argument\n`,
  },
  {
    name: "negative number value allowed",
    args: ["--data", "-5", "--verify_iat", "true"],
    code: 0,
    stdout: '{"data":"-5","verify_iat":"true"}\n',
    stderr: "",
  },
  {
    name: "-h short",
    args: ["-h"],
    code: 0,
    stdout: HELP,
    stderr: "",
  },
  {
    name: "--help long (even with other args)",
    args: ["--data", "x", "--help"],
    code: 0,
    stdout: HELP,
    stderr: "",
  },
  {
    name: "duplicate option takes last",
    args: ["--data", "a", "--data", "b", "--verify_iat", "false"],
    code: 0,
    stdout: '{"data":"b","verify_iat":"false"}\n',
    stderr: "",
  },
  {
    name: "non-ascii value passthrough",
    args: ["--data", "héllo", "--verify_iat", "true"],
    code: 0,
    stdout: '{"data":"héllo","verify_iat":"true"}\n',
    stderr: "",
  },
];

let failed = 0;
for (const c of cases) {
  const r = spawnSync("node", ["/tmp/driver17.mjs", ...c.args], {
    encoding: "utf8",
  });
  const ok =
    r.status === c.code && r.stdout === c.stdout && r.stderr === c.stderr;
  if (ok) {
    console.log(`PASS  ${c.name}`);
  } else {
    failed++;
    console.log(`FAIL  ${c.name}`);
    console.log(`  exit: got ${r.status}, want ${c.code}`);
    console.log(`  stdout: got ${JSON.stringify(r.stdout)}, want ${JSON.stringify(c.stdout)}`);
    console.log(`  stderr: got ${JSON.stringify(r.stderr)}, want ${JSON.stringify(c.stderr)}`);
  }
}
console.log(failed === 0 ? `\nAll ${cases.length} cases passed.` : `\n${failed} case(s) FAILED.`);
process.exit(failed === 0 ? 0 : 1);

