import { b64urlEncode, b64urlDecode } from '/output/lib/base64url.mjs';
import { pyJsonDumps } from '/output/lib/pyjson.mjs';
import { pyRepr } from '/output/lib/pyrepr.mjs';

let fails = 0;
function check(label, actual, expected) {
  const ok = actual === expected;
  if (!ok) fails++;
  console.log((ok ? 'PASS' : 'FAIL') + ' | ' + label);
  if (!ok) {
    console.log('  actual:   ' + actual);
    console.log('  expected: ' + expected);
  }
}

// Contract examples
check('pyRepr quote mix', pyRepr({info: `it's a "test"`, iat: 1}), `{'info': 'it\\'s a "test"', 'iat': 1}`);
check('pyJsonDumps ensure_ascii', pyJsonDumps({info:'héllo中文'}), '{"info":"h\\u00e9llo\\u4e2d\\u6587"}');
check('pyRepr basic', pyRepr({info: 'hello', iat: 1786345209}), `{'info': 'hello', 'iat': 1786345209}`);

// base64url: cross-check against Buffer (verification only, not in /output)
const cases = [new Uint8Array([]), new Uint8Array([0x66]), new Uint8Array([0x66,0x6f]), new Uint8Array([0x66,0x6f,0x6f]), new Uint8Array([0xff,0xee,0xdd,0x01]), new Uint8Array(256).map((_,i)=>i)];
for (const c of cases) {
  const mine = b64urlEncode(c);
  const ref = Buffer.from(c).toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  check('b64urlEncode len=' + c.length, mine, ref);
  const dec = b64urlDecode(mine);
  check('b64urlDecode len=' + c.length, Buffer.from(dec).equals(Buffer.from(c)), true);
}
check('b64urlDecode accepts padded', Buffer.from(b64urlDecode('Zm9v==')).toString(), 'foo');
check('b64urlDecode unpadded', Buffer.from(b64urlDecode('Zm8')).toString(), 'fo');

// More pyrepr/pyjson spot checks
check('pyRepr single quote only', pyRepr("it's"), `"it's"`);
check('pyRepr backslash+newline', pyRepr('a\\b\nc\td\re'), `'a\\\\b\\nc\\td\\re'`);
check('pyRepr printable non-ascii', pyRepr('héllo中文'), `'héllo中文'`);
check('pyRepr DEL escaped', pyRepr('a\x7fb'), `'a\\x7fb'`);
check('pyRepr ctrl', pyRepr('\x01\x1f'), `'\\x01\\x1f'`);
check('pyRepr bool/none', pyRepr({a: true, b: false, c: null}), `{'a': True, 'b': False, 'c': None}`);
check('pyRepr list', pyRepr([1, 'x', [2]]), `[1, 'x', [2]]`);
check('pyJsonDumps escapes', pyJsonDumps('a"b\\c\nd\te\rf\bg\fh'), '"a\\"b\\\\c\\nd\\te\\rf\\bg\\fh"');
check('pyJsonDumps astral', pyJsonDumps('😀'), '"\\ud83d\\ude00"');
check('pyJsonDumps compact', pyJsonDumps({a:1,b:[true,null,'x'],c:{}}), '{"a":1,"b":[true,null,"x"],"c":{}}');

console.log(fails === 0 ? 'ALL PASS' : fails + ' FAILURES');
process.exit(fails === 0 ? 0 : 1);

