    ])) for _ in range(n))
    # avoid lone surrogates which can't round-trip through JSON
    s = s.encode('utf-8', 'ignore').decode('utf-8', 'ignore')
    tests.append({"s": s,
                  "dumps": json.dumps(s, separators=(",", ":"), ensure_ascii=True),
                  "repr": repr(s)})
json.dump(tests, open("/tmp/fuzz_ref.json", "w"))
print("fuzz ref:", len(tests))
EOF
