import { readFileSync, writeFileSync } from 'node:fs';
const pyRanges = JSON.parse(readFileSync('/tmp/py_printable.json', 'utf8'));
const NON_PRINTABLE = /[\p{C}\p{Z}]/u;
function nodePrintable(cp) {
  if (cp === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}
let ri = 0;
function pyPrintable(cp) {
  while (ri < pyRanges.length && cp > pyRanges[ri][1]) ri++;
  return ri < pyRanges.length && cp >= pyRanges[ri][0] && cp <= pyRanges[ri][1];
}
const diffs = [];
for (let cp = 0x20; cp < 0x110000; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (nodePrintable(cp) !== pyPrintable(cp)) diffs.push(cp);
}
// compress to ranges
const ranges = [];
for (const cp of diffs) {
  if (ranges.length && cp === ranges[ranges.length-1][1] + 1) ranges[ranges.length-1][1] = cp;
  else ranges.push([cp, cp]);
}
console.log('disagreement count:', diffs.length, 'ranges:', ranges.length);
for (const [a,b] of ranges) console.log('0x' + a.toString(16), '- 0x' + b.toString(16), ' node=' + nodePrintable(a), 'py=' + pyPrintable(a));
writeFileSync('/tmp/disagree_ranges.json', JSON.stringify(ranges));
EOF
